{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 직원이 있는 공영주차장에 주차한 차량이 다른 차에 긁혀 가해자가 없을 때 주차장에 수리비 전액을 바로 청구할 수 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "조례는 주차장 관리자가 선량한 관리자의 주의의무를 다하여야 하고, 그 주의의무를 태만히 하지 아니하였음을 증명한 경우를 제외하고는 자동차의 훼손으로 인한 손해배상 책임을 면하지 못한다고 정합니다. 따라서 직원이 상주하는 공영주차장에 주차한 차량이 긁힌 경우, 관리자가 주의의무를 다하였음을 증명하지 못하면 손해배상 책임을 질 수 있습니다. 다만 조례가 수리비 전액을 바로 청구할 수 있는지, 청구 절차·범위·금액 산정 기준을 직접 정하지는 않으므로, 전액 즉시 청구 가능 여부는 이 조문만으로 단정되지 않습니다.",
          "b_ids": "주차장:제9조의2제1항, 주차장:제9조의2제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
